param(
  [Parameter(Mandatory = $true, Position = 0)]
  [string]$CommitMsgFile
)

$ErrorActionPreference = 'Stop'

if (-not (Test-Path -LiteralPath $CommitMsgFile)) {
  Write-Error '[commit-msg] commit message file not found.'
}

$lines = Get-Content -LiteralPath $CommitMsgFile
$subject = $lines |
  Where-Object { $_ -and ($_ -notmatch '^\s*#') } |
  Select-Object -First 1

if ([string]::IsNullOrWhiteSpace($subject)) {
  Write-Error '[commit-msg] empty commit subject is not allowed.'
}

# Merge/Revert commits can be auto-generated by git.
if ($subject -match '^(Merge|Revert)\b') {
  exit 0
}

$pattern = '^[a-z][a-z0-9-]*(\([^)]+\))?:\s.+$'
if ($subject -notmatch $pattern) {
  Write-Host '[commit-msg] invalid commit subject format.' -ForegroundColor Red
  Write-Host 'Expected: <type>[optional scope]: <description>' -ForegroundColor Yellow
  Write-Host 'Example : feat(timeline): optimize route rendering' -ForegroundColor Yellow
  exit 1
}

if ($subject.Length -gt 100) {
  Write-Host '[commit-msg] subject is too long (max 100 chars).' -ForegroundColor Red
  exit 1
}
